<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>Report Card</title><style>
@page{margin:28px 32px 42px}body{font-family:"DejaVu Sans",sans-serif;font-size:9px;color:#1f2937}table{width:100%;border-collapse:collapse}th,td{padding:5px;border:1px solid #9ca3af;vertical-align:top}th{background:#e5eef8;color:#123b66;text-align:left}thead{display:table-header-group}tr{page-break-inside:avoid}.header{border-bottom:2px solid #174b7a;padding-bottom:8px;margin-bottom:9px}.logo{width:65px;height:65px;object-fit:contain}.school-name{font-size:19px;font-weight:bold;color:#123b66}.muted{color:#64748b}.title{text-align:center;font-size:14px;font-weight:bold;margin:9px 0;color:#123b66}.section{font-size:10px;font-weight:bold;background:#174b7a;color:white;padding:5px;margin-top:9px}.info td{border:0;padding:3px 5px}.label{font-weight:bold;color:#334155}.summary td{width:25%}.remarks{border:1px solid #9ca3af;padding:6px;min-height:25px}.signatures{margin-top:18px}.signatures td{border:0;text-align:center;width:33%;padding-top:20px}.signature{max-width:90px;max-height:36px}.footer{position:fixed;bottom:-25px;left:0;right:0;text-align:center;font-size:8px;color:#64748b}.page-number:after{content:counter(page)}.nowrap{white-space:nowrap}
</style></head><body>
<div class="footer">{{ $settings?->report_footer }} @if($settings?->report_footer) | @endif Generated by ShuleOS | Page <span class="page-number"></span></div>
<table class="header"><tr><td style="width:78px;border:0">@if($logo)<img class="logo" src="{{ $logo }}" alt="School logo">@endif</td><td style="text-align:center;border:0"><div class="school-name">{{ $card->school->school_name }}</div>@if($settings?->school_motto)<div><em>{{ $settings->school_motto }}</em></div>@endif<div class="muted">{{ collect([$card->school->postal_address,$card->school->physical_address,$card->school->phone,$card->school->email,$card->school->website])->filter()->implode(' | ') }}</div>@if($settings?->report_header)<div>{{ $settings->report_header }}</div>@endif</td><td style="width:78px;border:0"></td></tr></table>
<div class="title">LEARNER PROGRESS REPORT / REPORT CARD</div>
<table class="info"><tr><td><span class="label">Learner:</span> {{ collect([$card->learner->first_name,$card->learner->middle_name,$card->learner->last_name])->filter()->implode(' ') }}</td><td><span class="label">Admission No:</span> {{ $card->learner->admission_no ?: '-' }}</td><td><span class="label">Assessment No:</span> {{ $card->learner->assessment_no ?: '-' }}</td></tr><tr><td><span class="label">Grade:</span> {{ $card->grade->grade_name ?? '-' }}</td><td><span class="label">Stream:</span> {{ $card->stream->stream_name ?? '-' }}</td><td><span class="label">Gender:</span> {{ $card->learner->gender ?: '-' }}</td></tr><tr><td><span class="label">Academic Year:</span> {{ $card->academicYear->year_name ?? $card->academicYear->academic_year ?? '-' }}</td><td><span class="label">Term:</span> {{ $card->term->term_name ?? '-' }}</td><td><span class="label">Exam:</span> {{ $card->exam->exam_name ?? '-' }}</td></tr></table>
<div class="section">Learning Area Performance</div><table><thead><tr><th>Learning Area</th><th>Marks</th><th>Max</th><th>%</th><th>Grade</th><th>Points</th><th>Teacher Comment</th></tr></thead><tbody>@foreach($card->learningAreas as $area)<tr><td>{{ $area->learningArea->learning_area_name ?? $area->learningArea->name ?? '-' }}</td><td>{{ $area->marks_obtained }}</td><td>{{ $area->maximum_marks }}</td><td>{{ $area->percentage }}</td><td>{{ $area->grade_code }}@if($area->gradingScale?->grade_description)<br><span class="muted">{{ $area->gradingScale->grade_description }}</span>@endif</td><td>{{ $area->points ?? '-' }}</td><td>{{ $area->teacher_comment ?: '-' }}</td></tr>@endforeach</tbody></table>
<div class="section">Overall Summary</div><table class="summary"><tr><td><span class="label">Overall Score:</span> {{ $card->overall_score }}</td><td><span class="label">Maximum:</span> {{ $card->maximum_marks }}</td><td><span class="label">Average:</span> {{ $card->average_percentage }}%</td><td><span class="label">Overall Grade:</span> {{ $card->overallGradingScale?->grade_code ?? $card->overall_grade }} {{ $card->overallGradingScale?->grade_description }}</td></tr><tr><td><span class="label">Total Points:</span> {{ $card->total_points ?? '-' }}</td><td><span class="label">Stream Position:</span> {{ $card->stream_position ?? '-' }}</td><td><span class="label">Grade Position:</span> {{ $card->grade_position ?? '-' }}</td><td><span class="label">School Position:</span> {{ $card->school_position ?? '-' }} / {{ $card->total_learners ?? '-' }}</td></tr></table>
<div class="section">Attendance</div>@if($card->attendance_total_sessions === null)<div class="remarks">Attendance data unavailable</div>@else<table><tr><td>Present: {{ $card->attendance_present }}</td><td>Absent: {{ $card->attendance_absent }}</td><td>Late: {{ $card->attendance_late }}</td><td>Total Sessions: {{ $card->attendance_total_sessions }}</td><td>Attendance: {{ $card->attendance_percentage }}%</td></tr></table>@endif
<div class="section">Remarks</div><table><tr><td><span class="label">Class Teacher:</span><div class="remarks">{{ $card->class_teacher_comment ?: '-' }}</div></td><td><span class="label">Principal:</span><div class="remarks">{{ $card->principal_comment ?: '-' }}</div></td></tr></table>
@if($card->pathwayRecommendation)<div class="section">Junior School Pathway Recommendation</div><table><tr><td><span class="label">Recommended Pathway:</span> {{ $card->pathwayRecommendation->recommended_pathway ?: '-' }}</td><td><span class="label">Confidence:</span> {{ $card->pathwayRecommendation->confidence_score !== null ? $card->pathwayRecommendation->confidence_score.'%' : '-' }}</td></tr><tr><td><span class="label">Strengths:</span> {{ $card->pathwayRecommendation->strengths ?: '-' }}</td><td><span class="label">Improvement Areas:</span> {{ $card->pathwayRecommendation->improvement_areas ?: '-' }}</td></tr></table>@endif
<table class="signatures"><tr><td>_________________________<br>Class Teacher Signature</td><td>@if($signature)<img class="signature" src="{{ $signature }}" alt="Principal signature"><br>@else_________________________<br>@endif{{ $settings?->principal_name ?: 'Principal' }}</td><td>_________________________<br>School Stamp</td></tr></table><div style="text-align:right;margin-top:9px">Generated: {{ $card->generated_at?->format('d M Y') ?? now()->format('d M Y') }}</div>
</body></html>
